const body = $json.body || $json;

function firstText(...vals) {
  for (const v of vals) {
    if (v !== undefined && v !== null && String(v).trim()) return String(v).trim();
  }
  return '';
}

const rawText = firstText(
  body.raw_text,
  body.chatInput,
  body.input,
  body.text,
  typeof body.message === 'string' ? body.message : '',
  body.prompt,
  body.query,
  body.command,
  body.body?.raw_text,
  body.body?.chatInput,
  body.body?.input,
  body.body?.text,
  typeof body.body?.message === 'string' ? body.body.message : '',
  body.message?.text,
  body.event?.text,
  body.update?.message?.text
);

let intent = String(body.intent || '').trim();
let target = body.target ?? body.vmid ?? body.name ?? body.label ?? null;
let confirmed = !!body.confirmed;
let requiresConfirmation = !!body.requires_confirmation;
let intentSource = intent ? 'structured_intent' : 'natural_language';

const text = rawText.toLowerCase()
  .replace(/[.,!?;:]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// Natural-language confirmation words for future approval flows.
if (!confirmed && /^(yes|yeah|yebo|yep|ok|okay|approved|approve|confirm|confirmed|do it|proceed)$/i.test(rawText.trim())) {
  confirmed = true;
}

function cleanTarget(s) {
  if (!s) return null;
  let t = String(s).trim();
  t = t.replace(/^(vm|machine|server|host)\s+/i, '');
  t = t.replace(/\s+(please|now)$/i, '');
  t = t.replace(/[^A-Za-z0-9_. -]/g, '').trim();
  return t || null;
}

function targetAfter(patterns) {
  for (const p of patterns) {
    const m = rawText.match(p);
    if (m && m[1]) return cleanTarget(m[1]);
  }
  return null;
}

if (!intent) {
  // Ghost VM/app unreachable and idle cleanup.
  if (/(cannot access|can't access|cant access|unreachable|not responding|app down|server down|service down|people cannot access)/.test(text)) {
    intent = 'recover_ghost_vm';
  }
  else if (/(idle|unused|cleanup|clean up|resource saving|save resources|old vms|waste)/.test(text) && /(vm|vms|machine|machines|lab|proxmox|server|servers)/.test(text)) {
    intent = 'cleanup_idle_vms';
  }
  // Safe patching / snapshot / rollback intents.
  if (/(safe|safely|patch|update|upgrade)/.test(text) && /(ubuntu|test|n8n|server|vm|machine|host)/.test(text)) {
    intent = 'safe_patch_vm';
  }
  else if (/(create|take|make)/.test(text) && /(snapshot|backup|restore point|safety point)/.test(text)) {
    intent = 'create_vm_snapshot';
  }
  else if (/(rollback|roll back|revert|restore)/.test(text) && /(snapshot|backup|vm|machine|server|ubuntu|test)/.test(text)) {
    intent = 'rollback_vm_snapshot';
  }
  // Resource diagnostics for one VM, e.g. "Ubuntu Test is slow", "check CPU/RAM of Ubuntu Test".
  else if (/(slow|lag|lagging|crash|crashing|freeze|freezing|resource|resources|ram|memory|cpu|disk|diagnose|diagnostic|why|performance|bottleneck)/.test(text) && /(ubuntu|test|n8n|server|vm|machine|host|gns|windows|desktop)/.test(text) && !/(all|every|summary of all)/.test(text)) {
    intent = 'diagnose_vm_resources';
  }
  // Detailed inventory/health summary with RAM, CPU, uptime, disk/network counters.
  else if (!intent && /(?:detail|details|detailed|full|complete|summary|information|info|resources|resource|ram|memory|cpu|usage|utilization)/.test(text) && !/\b(start|stop|shutdown|reboot|restart|reset|power on|power off|safe|safely|patch|update|upgrade)\b/.test(text)) {
    intent = 'list_vm_status';
    body.detail = true;
  }
  // IP discovery: tolerate typos like "vs" for "vms" and natural wording.
  else if (!intent && /(?:ip|ips|address|addresses)/.test(text) && /(vm|vms|vs|machine|machines|server|servers|host|hosts|all)/.test(text)) {
    intent = 'get_all_vm_ips';
  }
  // Explicit all-VM inventory/status.
  else if (!intent && /(?:list|show|check|get|display)/.test(text) && /(vm|vms|machine|machines|server|servers)/.test(text) && /(status|statuses|state|states|running|stopped|inventory|list)/.test(text)) {
    intent = 'list_vm_status';
  }
  // One VM status.
  else if (!intent && /(?:status|state|running|\bup\b|\bdown\b|health)/.test(text) && /(vm|machine|server|host|ubuntu|gns|windows|n8n|proxmox|test|desktop)/.test(text)) {
    intent = 'get_vm_status';
  }
  else if (!intent && /\b(start|power on|turn on|boot)\b/.test(text)) {
    intent = 'start_vm';
  }
  else if (!intent && /\b(stop|shutdown|shut down|power off|turn off)\b/.test(text)) {
    intent = 'stop_vm';
  }
  else if (!intent && /\b(reboot|restart|reset)\b/.test(text)) {
    intent = 'reboot_vm';
  }
}

if (!target) {
  target = targetAfter([
    /(?:status|state|health)\s+(?:of|for)?\s*(?:the)?\s*(.+)$/i,
    /(?:start|stop|shutdown|reboot|restart|reset|boot)\s+(?:the)?\s*(.+)$/i,
    /(?:vm|machine|server|host)\s+(?:called|named)?\s*(.+)$/i,
    /(?:ubuntu\s*test|ubuntutest|mlab\s*test|mlab-test|n8n\s*server|gns3|gns3-vm|ubuntu\s*desktop|windows|wineleven)/i
  ]);
  // If targetAfter matched the whole known-name regex, use the actual match.
  if (!target) {
    const known = rawText.match(/(ubuntu\s*test|ubuntutest|mlab\s*test|mlab-test|n8n\s*server|mlabubuntuserv|gns3-vm107|gns3|ubuntu\s*desktop|ubuntuDesk24\.04|wineleven|windows)/i);
    if (known) target = cleanTarget(known[1]);
  }
}

// Canonicalize common spoken labels to Proxmox labels where useful.
const canonical = {
  'ubuntu test': 'UbuntuTest',
  'ubuntutest': 'UbuntuTest',
  'mlab test': 'UbuntuTest',
  'mlab-test': 'UbuntuTest',
  'n8n server': 'MlabUbuntuServ',
  'mlabubuntuserv': 'MlabUbuntuServ',
  'gns3': 'GNS3-VM107',
  'gns3-vm': 'GNS3-VM107',
  'gns3-vm107': 'GNS3-VM107',
  'ubuntu desktop': 'UbuntuDesk24.04',
  'ubuntudesk24.04': 'UbuntuDesk24.04',
  'windows': 'WinEleven',
  'wineleven': 'WinEleven'
};
if (target) {
  const key = String(target).toLowerCase().replace(/\s+/g, ' ').trim();
  target = canonical[key] || target;
}

return [{ json: {
  source: body.source || 'openclaw',
  channel: body.channel || 'telegram',
  user_id: body.user_id || null,
  user_name: body.user_name || null,
  raw_text: rawText,
  intent,
  intent_source: intentSource,
  target,
  confirmed,
  requires_confirmation: requiresConfirmation,
  detail: !!(body.detail || body.detailed || /\b(detail|details|detailed|full|complete|summary|information|info|resources|resource|ram|memory|cpu|usage|utilization)\b/i.test(rawText)),
  request_id: body.request_id || null
}}];

const req = $('Parse OpenClaw Request').first().json;
const vms = Array.isArray($json.data) ? $json.data : [];
function gb(bytes) {
  const n = Number(bytes || 0);
  if (!n) return '0 GB';
  return (n / 1024 / 1024 / 1024).toFixed(1) + ' GB';
}
function pct(frac) {
  const n = Number(frac || 0) * 100;
  return n.toFixed(n >= 10 ? 1 : 2) + '%';
}
function uptime(sec) {
  sec = Number(sec || 0);
  if (!sec) return '-';
  const d = Math.floor(sec / 86400);
  const h = Math.floor((sec % 86400) / 3600);
  const m = Math.floor((sec % 3600) / 60);
  return `${d}d ${h}h ${m}m`;
}
function statusIcon(s) {
  return s === 'running' ? '🟢' : s === 'stopped' ? '🔴' : '🟡';
}
function bytesHuman(bytes) {
  let n = Number(bytes || 0);
  const units = ['B','KB','MB','GB','TB'];
  let i = 0;
  while (n >= 1024 && i < units.length - 1) { n /= 1024; i++; }
  return `${n.toFixed(i ? 1 : 0)} ${units[i]}`;
}
const data = vms.map(vm => {
  const mem = Number(vm.mem || 0);
  const maxmem = Number(vm.maxmem || 0);
  const memPct = maxmem ? (mem / maxmem * 100) : 0;
  return {
    vmid: String(vm.vmid),
    name: vm.name,
    node: vm.node,
    status: vm.status,
    type: vm.type,
    cpu_usage: pct(vm.cpu),
    cpu_cores: vm.maxcpu || null,
    ram_used: gb(vm.mem),
    ram_total: gb(vm.maxmem),
    ram_usage: memPct.toFixed(1) + '%',
    disk_size: gb(vm.maxdisk),
    disk_read: bytesHuman(vm.diskread),
    disk_write: bytesHuman(vm.diskwrite),
    net_in: bytesHuman(vm.netin),
    net_out: bytesHuman(vm.netout),
    uptime: uptime(vm.uptime)
  };
});
const running = data.filter(v => v.status === 'running').length;
const stopped = data.filter(v => v.status === 'stopped').length;
const lines = [];
lines.push('🖥️ *Proxmox VM Detailed Summary*');
lines.push(`📊 Total: ${data.length} | 🟢 Running: ${running} | 🔴 Stopped: ${stopped}`);
lines.push('');
for (const vm of data) {
  lines.push(`${statusIcon(vm.status)} *${vm.vmid} — ${vm.name}*`);
  lines.push(`   📍 Node: ${vm.node} | State: ${vm.status}`);
  lines.push(`   🧠 RAM: ${vm.ram_used} / ${vm.ram_total} (${vm.ram_usage})`);
  lines.push(`   ⚙️ CPU: ${vm.cpu_usage} of ${vm.cpu_cores ?? '-'} cores`);
  lines.push(`   💾 Disk: ${vm.disk_size} | Read ${vm.disk_read} / Write ${vm.disk_write}`);
  lines.push(`   🌐 Net: In ${vm.net_in} / Out ${vm.net_out}`);
  lines.push(`   ⏱️ Uptime: ${vm.uptime}`);
  lines.push('');
}
return [{ json: { success: true, intent: 'list_vm_status', detail: !!req.detail, count: data.length, summary: { total: data.length, running, stopped }, message: lines.join('\n'), data } }];

const req = $('Parse OpenClaw Request').first().json;
const target = req.target || {};
const vmid = String(target.vmid || '');
const vms = Array.isArray($json.data) ? $json.data : [];
const match = vms.find(vm => String(vm.vmid) === vmid);
if (!match) { return [{ json: { success: false, intent: 'get_vm_status', error: 'vm_not_found', target } }]; }
return [{ json: { success: true, intent: 'get_vm_status', target, data: { vmid: String(match.vmid), name: match.name, node: match.node, status: match.status, type: match.type } } }];

const base = $('VM Running For IP?').item.json;
const resolver = $json;
const data = resolver.data && !Array.isArray(resolver.data) ? resolver.data : resolver;
const ipv4 = data.ipv4 || (Array.isArray(data.ips) ? (data.ips.find(i => i.version === 4)?.ip) : null);
const ip = ipv4 || data.ip || null;
return [{ json: {
  vmid: base.vmid,
  name: base.name,
  node: base.node,
  status: base.status,
  type: base.type,
  mac: data.mac || null,
  ip,
  ipv4: ipv4 || null,
  ips: data.ips || [],
  ip_source: ip ? (ipv4 ? 'proxmox-arp-ipv4' : 'proxmox-arp') : null,
  resolver_success: resolver.success ?? !!ip,
  note: ip ? null : 'no_ip_found_by_proxmox_ip_resolver'
} }];

const input = $json;
let data = [];
if (Array.isArray(input.data)) data = input.data;
else if (Array.isArray(input.results)) data = input.results;
else data = $input.all().map(i => i.json);

function normalizeIps(v) {
  if (!v) return [];
  if (Array.isArray(v)) return v;
  if (typeof v === 'object') return [v];
  return [];
}
function statusIcon(status) {
  if (status === 'running') return '🟢';
  if (status === 'stopped') return '🔴';
  return '🟡';
}
function ipText(vm) {
  const ip = vm.ipv4 || vm.ip || null;
  if (ip) return ip;
  if (vm.status === 'running') return 'No IP found yet';
  return 'VM stopped';
}

data = data.map(vm => ({
  vmid: String(vm.vmid ?? ''),
  name: vm.name ?? vm.label ?? '',
  node: vm.node ?? '',
  status: vm.status ?? '',
  type: vm.type ?? 'qemu',
  mac: vm.mac ?? null,
  ip: vm.ipv4 || vm.ip || null,
  ipv4: vm.ipv4 || (vm.ip && /^\d+\./.test(vm.ip) ? vm.ip : null),
  ips: normalizeIps(vm.ips),
  ip_source: (vm.ipv4 || vm.ip) ? (vm.ip_source || vm.ipsource || 'proxmox-mac-arp-resolver') : null,
  note: (vm.ipv4 || vm.ip) ? null : (vm.status === 'running' ? 'no_ip_found_in_arp_or_arp_scan' : 'vm_not_running')
}));

const running = data.filter(v => v.status === 'running').length;
const withIp = data.filter(v => v.ipv4 || v.ip).length;
const lines = [];
lines.push('🌐 *Proxmox VM IP Address Summary*');
lines.push(`📦 Total VMs: ${data.length} | 🟢 Running: ${running} | ✅ With IPv4: ${withIp}`);
lines.push('');
for (const vm of data) {
  lines.push(`${statusIcon(vm.status)} *${vm.vmid} — ${vm.name || 'Unnamed VM'}*`);
  lines.push(`   📡 Status: ${vm.status || 'unknown'} | 📍 Node: ${vm.node || '-'}`);
  lines.push(`   🌍 IPv4: ${ipText(vm)}`);
  if (vm.mac) lines.push(`   🔗 MAC: ${vm.mac}`);
  if (vm.ip_source) lines.push(`   🧭 Source: ${vm.ip_source}`);
  if (vm.note === 'vm_not_running') lines.push('   ℹ️ Note: VM is stopped, so no live IP is expected.');
  else if (vm.note) lines.push(`   ⚠️ Note: ${vm.note}`);
  lines.push('');
}
lines.push('💡 IPs are resolved agentlessly from Proxmox VM metadata, bridge neighbor table, and arp-scan.');

return [{ json: { success: true, intent: 'get_all_vm_ips', count: data.length, data, message: lines.join('\n') } }];

const req = $('Parse OpenClaw Request').first().json;
const target = req.target || {};
const vmid = String(target.vmid || '');
const vms = Array.isArray($json.data) ? $json.data : [];
const match = vms.find(vm => String(vm.vmid) === vmid);
if (!match) return [{ json: { success: false, intent: 'start_vm', error: 'vm_not_found', target } }];
return [{ json: { success: true, intent: 'start_vm', target, vmid: String(match.vmid), vmName: match.name, vmNode: match.node, vmType: match.type, status_before: match.status } }];

const req = $('Parse OpenClaw Request').first().json;
const target = req.target || {};
const vmid = String(target.vmid || '');
const vms = Array.isArray($json.data) ? $json.data : [];
const match = vms.find(vm => String(vm.vmid) === vmid);
if (!match) return [{ json: { success: false, intent: 'stop_vm', error: 'vm_not_found', target } }];
return [{ json: { success: true, intent: 'stop_vm', target, vmid: String(match.vmid), vmName: match.name, vmNode: match.node, vmType: match.type, status_before: match.status } }];

const req = $('Parse OpenClaw Request').first().json;
const target = req.target || {};
const vmid = String(target.vmid || '');
const vms = Array.isArray($json.data) ? $json.data : [];
const match = vms.find(vm => String(vm.vmid) === vmid);
if (!match) return [{ json: { success: false, intent: 'reboot_vm', error: 'vm_not_found', target } }];
return [{ json: { success: true, intent: 'reboot_vm', target, vmid: String(match.vmid), vmName: match.name, vmNode: match.node, vmType: match.type, status_before: match.status } }];
